// argparse.mjs - minimal Python argparse mimic for the test17 CLI.

const USAGE = (prog) => `usage: ${prog} [-h] --data DATA --verify_iat {true,false}`;

const HELP = (prog) => `${USAGE(prog)}

options:
  -h, --help            show this help message and exit
  --data DATA
  --verify_iat {true,false}`;

function error(prog, message) {
  process.stderr.write(USAGE(prog) + '\n');
  process.stderr.write(`${prog}: error: ${message}\n`);
  process.exit(2);
}

const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

function looksLikeOption(token) {
  return token.length > 1 && token[0] === '-' && !NEGATIVE_NUMBER.test(token);
}

export function parseArgs(argv, prog) {
  const values = { data: undefined, verify_iat: undefined };
  const unrecognized = [];

  let i = 0;
  while (i < argv.length) {
    const arg = argv[i];
    if (arg === '-h' || arg === '--help') {
      process.stdout.write(HELP(prog) + '\n');
      process.exit(0);
    }
    let name = null;
    let inlineValue = null;
    if (arg === '--data' || arg === '--verify_iat') {
      name = arg;
    } else if (arg.startsWith('--data=')) {
      name = '--data';
      inlineValue = arg.slice('--data='.length);
    } else if (arg.startsWith('--verify_iat=')) {
      name = '--verify_iat';
      inlineValue = arg.slice('--verify_iat='.length);
    } else {
      unrecognized.push(arg);
      i += 1;
      continue;
    }

    let value;
    if (inlineValue !== null) {
      value = inlineValue;
      i += 1;
    } else {
      const next = argv[i + 1];
      if (next === undefined || looksLikeOption(next)) {
        error(prog, `argument ${name}: expected one argument`);
      }
      value = next;
      i += 2;
    }

    if (name === '--verify_iat' && value !== 'true' && value !== 'false') {
      error(prog, `argument --verify_iat: invalid choice: '${value}' (choose from 'true', 'false')`);
    }
    values[name.slice(2)] = value;
  }

  const missing = [];
  if (values.data === undefined) missing.push('--data');
  if (values.verify_iat === undefined) missing.push('--verify_iat');
  if (missing.length > 0) {
    error(prog, `the following arguments are required: ${missing.join(', ')}`);
  }
  if (unrecognized.length > 0) {
    error(prog, `unrecognized arguments: ${unrecognized.join(' ')}`);
  }
  return values;
}
```

